{
  "attacks": [
    {
      "id": "C1",
      "claim": "Every generated formatter (integer-key and string-key), enum formatter, union formatter, resolver (with its two nested helper classes) and composite resolver is decorated with ExcludeFromCodeCoverage.",
      "outcome": "could_not_falsify"
    },
    {
      "id": "C2",
      "claim": "The new test verifies that every type the generator emits is decorated.",
      "outcome": "scenario_proposed",
      "scenario": "The test only verifies that the generated file contains the attribute string at least once, and that all occurrences of the attribute string are guarded. It does not verify that every type in the file is decorated. A file with multiple types where only one is decorated would still pass the test.",
      "test_sketch": "Modify the generator to omit the attribute from one of the nested types (e.g., `FormatterCache<T>`). Run the `AllGeneratedTypesAreExcludedFromCodeCoverage` test. The test will still pass because the file still contains the attribute on the main resolver class.",
      "citations": [
        {
          "path": "tests/MessagePack.SourceGenerator.Tests/CodeCoverageExclusionTests.cs",
          "line": 76,
          "quote": "text.Contains(ExcludeAttribute),"
        }
      ]
    },
    {
      "id": "C3",
      "claim": "Wrapping the attribute in '#if !NETSTANDARD2_0 && !NETFRAMEWORK' is needed and sufficient so that consumers targeting netstandard2.0 or .NET Framework still compile.",
      "outcome": "scenario_proposed",
      "scenario": "The attribute `System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage` is actually available in both .NET Standard 2.0 and .NET Framework 4.0+. Therefore, the guard is not needed for these targets to compile.",
      "test_sketch": "Create a project targeting `netstandard2.0` and another targeting `net472`. Add a class decorated with `[global::System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage]` to both. Run `dotnet build`. Both projects will compile successfully without needing the `#if` guard.",
      "citations": [
        {
          "path": "tests/MessagePack.SourceGenerator.Tests/CodeCoverageExclusionTests.cs",
          "line": 18,
          "quote": "The attribute is not available on netstandard2.0 or .NET Framework, so it is only emitted where it exists."
        }
      ]
    },
    {
      "id": "C4",
      "claim": "The only change to generated output is the added guarded attribute.",
      "outcome": "scenario_proposed",
      "scenario": "The change also modifies the whitespace formatting for types with generic constraints. The opening brace now always has a preceding newline, whereas previously it did not if `anyConstraints` was true.",
      "test_sketch": "Generate a formatter for a generic type with constraints. Compare the generated output before and after the change. The opening brace will now be on a new line (`{\\r\\n`) instead of the same line (`{`).",
      "citations": [
        {
          "path": "src/MessagePack.SourceGenerator/Transforms/TransformUtilities.cs",
          "line": 58,
          "quote": "writer(anyConstraints ? \"{\\r\\n\" : \" {\\r\\n\");"
        }
      ]
    },
    {
      "id": "C5",
      "claim": "Each .tt template and its preprocessed .cs output carry the same attribute text.",
      "outcome": "could_not_falsify"
    },
    {
      "id": "C6",
      "claim": "All generated formatters and resolvers are decorated with ExcludeFromCodeCoverage.",
      "outcome": "scenario_proposed",
      "scenario": "The attribute is conditionally compiled. If the project targets `.NET Standard 2.0` or `.NET Framework` (i.e., `NETSTANDARD2_0` or `NETFRAMEWORK` is defined), the attribute is omitted from the compiled code.",
      "test_sketch": "Compile the generated code with the `NETSTANDARD2_0` preprocessor symbol defined. Use reflection to inspect the generated formatter or resolver types. They will not have the `ExcludeFromCodeCoverage` attribute.",
      "citations": [
        {
          "path": "README.md",
          "line": 1640,
          "quote": "The attribute is only emitted for targets where it is available (not `netstandard2.0` or .NET Framework)."
        }
      ]
    },
    {
      "id": "C7",
      "claim": "All snapshot files affected by the change were regenerated: 222 of the 225 .g.cs snapshots were updated and the 3 left untouched are not consumed by any test.",
      "outcome": "could_not_falsify"
    },
    {
      "id": "C8",
      "claim": "The change affects only generated code: coverage exclusion is limited to code the generator emits.",
      "outcome": "scenario_proposed",
      "scenario": "The generator applies the `[ExcludeFromCodeCoverage]` attribute to the `partial class` of the resolver. In C#, attributes applied to one part of a partial class apply to the entire class. Therefore, any user-written code in the other part of the partial class will also be excluded from code coverage.",
      "test_sketch": "Define a `partial class GeneratedMessagePackResolver` with a custom method. Run the generator to emit the other part of the partial class. Compile and check the custom method's coverage or inspect the class attributes via reflection; the entire class (including the user's custom method) will have the `ExcludeFromCodeCoverage` attribute.",
      "citations": [
        {
          "path": "src/MessagePack.SourceGenerator/Transforms/ResolverTemplate.tt",
          "line": 17,
          "quote": "partial class <#= ResolverName.Name #> : MsgPack::IFormatterResolver"
        }
      ]
    }
  ]
}
